import json
import os

# Look for any existing result files that might show the mapping
for root, dirs, files in os.walk('.'):
    for file in files:
        if file.endswith('.json') and 'results' in root:
            filepath = os.path.join(root, file)
            try:
                with open(filepath) as f:
                    data = json.load(f)
                    if isinstance(data, list) and len(data) > 0:
                        first_item = data[0]
                        if 'question' in first_item or 'nodes' in first_item:
                            print(f"Found file: {filepath}")
                            print(json.dumps(first_item, indent=2)[:500])
                            break
            except:
                pass
    if root.endswith('results'):
        break
